func decodeResult[T any](payload any) (T, error) {
	var result T
	raw, err := json.Marshal(payload)
	if err != nil {
		return result, err
	}
	if err := json.Unmarshal(raw, &result); err != nil {
		return result, err
	}
	return result, nil
}
